function fieldInput(f,table){let bool=['is_active','is_published','randomize_questions','randomize_options','warn_on_tab_switch','log_tab_switches','require_fullscreen','prevent_copy_paste','allow_resume','show_results','show_correct_answers'].includes(f);let type=f.includes('_at')||f.endsWith('_date')?'datetime-local':['price','sale_price','capacity','display_order','duration_minutes','total_marks','max_attempts','device_limit','default_marks','default_negative_marks','discount_value','max_discount','min_purchase','usage_limit','per_user_limit'].includes(f)?'number':'text';let courseStatus=table==='courses'&&f==='status';return `<div class="field"><label>${esc(f.replaceAll('_',' '))}</label>${courseStatus?`<select name="${f}"><option value="draft">Draft (not visible)</option><option value="published">Published (visible)</option><option value="archived">Archived</option></select>`:bool?`<select name="${f}"><option value="true">Yes</option><option value="false">No</option></select>`:f==='description'||f==='detailed_information'||f==='routine'||f==='message'||f==='instructions'||f==='question_text'||f==='correct_answer_text'||f==='explanation'||f==='setting_value'?`<textarea name="${f}"></textarea>`:`<input name="${f}" type="${type}" ${type==='number'?'step="any"':''} ${['title','name','code','slug','question_text','setting_key'].includes(f)?'required':''}>`}</div>`}
async function adminExamManager(){let [exams,courses]=await Promise.all([publicData('exams').catch(()=>[]),publicData('courses').catch(()=>[])]);let opts=courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('');return shell(`<div class="page-title"><div><h1>Exam management</h1><p>Create course exams, set the opening and closing time, and import questions from Excel.</p></div><button class="btn btn-primary" id="new-exam">＋ Create exam</button></div><section class="panel"><div class="panel-head"><h3>Examinations</h3><span class="muted">${exams.length} total</span></div><div class="table-wrap"><table><thead><tr><th>Exam</th><th>Course / batch link</th><th>Start</th><th>End</th><th>Status</th><th>Questions</th></tr></thead><tbody>${exams.length?exams.map(e=>`<tr><td><strong>${esc(e.title)}</strong></td><td>${esc(e.batch_id||'Course exam')}</td><td>${date(e.start_time)}</td><td>${date(e.end_time)}</td><td>${status(e.status)}</td><td><a class="btn btn-outline btn-sm" href="#exam-info/${e.id}">View questions →</a></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">No exams created yet.</div></td></tr>`}</tbody></table></div></section><div id="exam-create-host" data-courses="${esc(JSON.stringify(courses.map(c=>({id:c.id,title:c.title}))))}"></div>`,'admin-exams')}
function showExamCreate(){let host=$('#exam-create-host'),courses=JSON.parse(host.dataset.courses||'[]');host.innerHTML=`<div class="modal-backdrop" id="exam-modal"><form class="modal exam-create-modal" id="exam-create-form"><h2>Create a course examination</h2><p class="muted">Choose the course and exam schedule. Batch linking is handled automatically in the background.</p><div class="field"><label>Course</label><select name="course_id" required>${courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></div><div class="field"><label>Exam title</label><input name="title" required placeholder="e.g. DU A Unit Model Test 01"></div><div class="field"><label>Description / instructions</label><textarea name="instructions" placeholder="Instructions for students"></textarea></div><div class="form-grid"><div class="field"><label>Exam opens</label><input name="start_time" type="datetime-local" required></div><div class="field"><label>Exam closes</label><input name="end_time" type="datetime-local" required></div><div class="field"><label>Duration (minutes)</label><input name="duration" type="number" min="1" value="60" required></div><div class="field"><label>Exam type</label><select name="exam_type"><option value="daily">Daily</option><option value="final">Final</option><option value="weekly">Weekly</option><option value="mock">Mock</option></select></div></div><div class="field"><label>Question Excel file (.xlsx)</label><input name="questions" id="exam-xlsx" type="file" accept=".xlsx,.xls,.csv" required><small class="muted">Use the template to prepare your MCQ and written questions.</small></div><div class="toolbar"><button type="button" class="btn btn-outline" id="download-question-template">Download Excel template</button><span id="question-file-status" class="muted">No file selected</span></div><div class="field"><label><input type="checkbox" name="publish" style="width:auto"> Publish immediately after creation</label></div><div class="modal-actions"><button type="button" class="btn btn-outline" id="cancel-exam-modal">Cancel</button><button class="btn btn-primary" id="save-exam-btn">Create exam</button></div></form></div>`;$('#cancel-exam-modal').onclick=()=>$('#exam-modal').remove();$('#exam-xlsx').onchange=e=>$('#question-file-status').textContent=e.target.files[0]?.name||'No file selected';$('#download-question-template').onclick=downloadQuestionTemplate;$('#exam-create-form').onsubmit=async e=>{try{await createExamFromExcel(e)}catch(x){err(x)}}}
function downloadQuestionTemplate(){if(!window.XLSX){toast('Excel library is still loading. Refresh and try again.',true);return}let rows=[['question_type','question_text','option_a','option_b','option_c','option_d','correct_option','answer_text','explanation','marks','negative_marks'],['mcq','What is 2 + 2?','3','4','5','6','B','','Basic arithmetic',1,0.25],['written','Explain Newton\'s first law.','','','','','','An object remains at rest or in uniform motion unless acted upon by a net external force.','Law of inertia',5,0]];let ws=XLSX.utils.aoa_to_sheet(rows),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Questions');XLSX.writeFile(wb,'AdmiRank-Question-Template.xlsx')}
async function createExamFromExcel(e){e.preventDefault();let form=e.target,fd=new FormData(form),file=fd.get('questions'),btn=$('#save-exam-btn');if(!window.XLSX)throw Error('Excel parser is not ready. Refresh the page and try again.');if(!file||!file.size)throw Error('Choose an Excel question file.');btn.disabled=true;btn.textContent='Importing questions…';try{let wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});if(!rows.length)throw Error('The Excel sheet has no questions.');let normalized=rows.map((r,i)=>({type:String(r.question_type||'mcq').trim().toLowerCase(),text:String(r.question_text||'').trim(),opts:['A','B','C','D'].map(k=>String(r['option_'+k.toLowerCase()]||'').trim()).filter(Boolean),correct:String(r.correct_option||'').trim().toUpperCase(),answer:String(r.answer_text||'').trim(),explanation:String(r.explanation||'').trim(),marks:Number(r.marks||1),negative:Number(r.negative_marks||0),order:i+1}));for(let q of normalized){if(!q.text)throw Error(`Question ${q.order}: question_text is required.`);if(q.type==='mcq'&&(q.opts.length<2||!['A','B','C','D'].includes(q.correct)))throw Error(`Question ${q.order}: MCQ needs at least 2 options and correct_option A/B/C/D.`);if(!['mcq','written','short_answer','creative'].includes(q.type))throw Error(`Question ${q.order}: unsupported question_type ${q.type}.`)}let course=await result(sb.from('courses').select('*').eq('id',fd.get('course_id')).single());let batches=await result(sb.from('batches').select('id').eq('course_id',course.id).limit(1)).catch(()=>[]);let batchId=batches[0]?.id;if(!batchId){let made=await result(sb.from('batches').insert({course_id:course.id,name:`${course.title} — Course Exams`,batch_code:`AUTO-${course.id.slice(0,8)}`,description:'System-managed course exam grouping.',status:'published'}).select('id').single());batchId=made.id}let start=new Date(fd.get('start_time')),end=new Date(fd.get('end_time'));if(!(end>start))throw Error('Exam closing time must be after opening time.');let total=normalized.reduce((a,q)=>a+q.marks,0);let exam=await result(sb.from('exams').insert({batch_id:batchId,title:fd.get('title'),description:fd.get('instructions')||null,instructions:fd.get('instructions')||null,exam_type:fd.get('exam_type'),start_time:start.toISOString(),end_time:end.toISOString(),duration_minutes:Number(fd.get('duration')),total_marks:total,status:fd.get('publish')==='on'?'published':'draft',created_by:state.user.id}).select('id').single());for(let q of normalized){let eq=await result(sb.from('exam_questions').insert({exam_id:exam.id,question_order:q.order,question_type:q.type,question_text_snapshot:q.text,correct_answer_text_snapshot:q.answer||null,explanation_snapshot:q.explanation||null,image_paths_snapshot:[],marks:q.marks,negative_marks:q.negative}).select('id').single());if(q.type==='mcq'){let letters=['A','B','C','D'];let correctIdx=letters.indexOf(q.correct);await result(sb.from('exam_question_options').insert(q.opts.map((o,i)=>({exam_question_id:eq.id,option_label:letters[i],option_text:o,is_correct:i===correctIdx,display_order:i+1}))))}}toast(`Exam created with ${normalized.length} questions.`);render()}catch(err){throw err}finally{btn.disabled=false;btn.textContent='Create exam'}}
async function adminCrud(route){if(route==='admin-exams')return await adminExamManager();let def=adminDefs[route];let tab=new URLSearchParams(location.hash.split('?')[1]||'').get('table');let active=def.tables.find(t=>t.table===tab)||def.tables[0];let rows=await publicData(active.table).catch(()=>[]);let displayFields=active.table==='courses'?['title','slug','price','sale_price','status']:active.fields.slice(0,5);return shell(`<div class="page-title"><div><h1>${def.title}</h1><p>Manage courses, publish or unpublish them, and create separate enrollment batches.</p></div><button class="btn btn-primary" id="add-record">＋ Add ${active.label.slice(0,-1)}</button></div><div class="toolbar" style="margin-bottom:18px">${def.tables.map(t=>`<a class="btn ${t.table===active.table?'btn-primary':'btn-outline'} btn-sm" href="#${route}?table=${t.table}">${t.label}</a>`).join('')}</div><section class="panel"><div class="panel-head"><h3>${active.label}</h3><span class="muted">${rows.length} records</span></div><div class="table-wrap"><table><thead><tr>${displayFields.map(f=>`<th>${esc(f.replaceAll('_',' '))}</th>`).join('')}<th>Actions</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${displayFields.map(f=>`<td>${f==='status'?status(r[f]):typeof r[f]==='boolean'?status(r[f]?'active':'draft'):esc(String(r[f]??'—').slice(0,70))}</td>`).join('')}<td><button class="btn btn-outline btn-sm" data-edit="${r.id}">Edit</button> ${active.table==='courses'?`<button class="btn btn-${r.status==='published'?'outline':'primary'} btn-sm" data-course-publish="${r.id}" data-current-status="${esc(r.status||'')}">${r.status==='published'?'Unpublish':'Publish'}</button>`:''} <button class="btn btn-danger btn-sm" data-delete="${r.id}">Delete</button></td></tr>`).join(''):`<tr><td colspan="${displayFields.length+1}"><div class="empty">No ${active.label.toLowerCase()} found.</div></td></tr>`}</tbody></table></div></section>`,route)}
async function showAdminForm(table,fields,row){let courses=table==='batches'?await publicData('courses').catch(()=>[]):[];let html=`<div class="modal-backdrop" id="modal"><form class="modal" id="record-form"><h2>${row?'Edit':'Add'} ${table.replaceAll('_',' ')}</h2>${fields.map(f=>table==='batches'&&f==='course_id'?`<div class="field"><label>Course</label><select name="course_id" required><option value="">Select a course</option>${courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></div>`:fieldInput(f,table)).join('')}<div class="modal-actions"><button type="button" class="btn btn-outline" id="cancel-modal">Cancel</button><button class="btn btn-primary">Save record</button></div></form></div>`;document.body.insertAdjacentHTML('beforeend',html);let form=$('#record-form');if(row)for(let f of fields){let el=form.elements[f];if(el){let v=row[f];el.value=el.type==='datetime-local'&&v?new Date(v).toISOString().slice(0,16):v??''}}$('#cancel-modal').onclick=()=>$('#modal').remove();form.onsubmit=async e=>{e.preventDefault();let fd=new FormData(form),obj={};for(let f of fields){let el=form.elements[f],v=fd.get(f);if(el.tagName==='SELECT'&&['is_active','is_published','randomize_questions','randomize_options','warn_on_tab_switch','log_tab_switches','require_fullscreen','prevent_copy_paste','allow_resume','show_results','show_correct_answers'].includes(f))obj[f]=v==='true';else if(el.type==='number')obj[f]=v===''?null:Number(v);else if(el.type==='datetime-local')obj[f]=v?new Date(v).toISOString():null;else obj[f]=v===''?null:v}try{let q=sb.from(table);let res=row?await q.update(obj).eq('id',row.id):await q.insert(obj);if(res.error)throw res.error;$('#modal').remove();toast('Record saved.');render()}catch(e){err(e)}}}
async function paymentsPage(){let ps=await publicData('payments').catch(()=>[]);return shell(`<div class="page-title"><div><h1>Payment verification</h1><p>Manually verify bKash, Nagad and Rocket transactions before activating enrollments.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Amount</th><th>Method</th><th>Transaction ID</th><th>Sender phone</th><th>Submitted</th><th>Status</th><th>Action</th></tr></thead><tbody>${ps.length?ps.map(p=>`<tr><td><strong>${money(p.amount)}</strong></td><td>${esc(p.payment_method)}</td><td>${esc(p.transaction_id)}</td><td>••${esc(p.sender_phone_last2||'')}</td><td>${date(p.submitted_at)}</td><td>${status(p.status)}</td><td>${p.status==='pending'?`<button class="btn btn-primary btn-sm" data-approve="${p.id}">Approve</button> <button class="btn btn-danger btn-sm" data-reject="${p.id}">Reject</button>`:'—'}</td></tr>`).join(''):'<tr><td colspan="7"><div class="empty">No payment submissions.</div></td></tr>'}</tbody></table></div></section>`)}
