async function usersPage(){let [users,assign]=await Promise.all([publicData('profiles').catch(()=>[]),publicData('evaluator_assignments').catch(()=>[])]);return shell(`<div class="page-title"><div><h1>Users & evaluator assignments</h1><p>Review profile records and assigned examination evaluators.</p></div></div><section class="panel"><h3>Student profiles</h3><div class="table-wrap"><table><thead><tr><th>Student ID</th><th>Name</th><th>Phone</th><th>School</th><th>College</th></tr></thead><tbody>${users.length?users.map(u=>`<tr><td>${esc(u.student_id)}</td><td><strong>${esc(u.full_name)}</strong></td><td>${esc(u.phone)}</td><td>${esc(u.school)}</td><td>${esc(u.college)}</td></tr>`).join(''):'<tr><td colspan="5"><div class="empty">No profile records are accessible.</div></td></tr>'}</tbody></table></div></section><section class="panel"><h3>Evaluator assignments</h3><div class="table-wrap"><table><thead><tr><th>Evaluator user ID</th><th>Exam ID</th><th>Assigned</th><th>Status</th></tr></thead><tbody>${assign.length?assign.map(a=>`<tr><td>${esc(a.evaluator_id)}</td><td>${esc(a.exam_id)}</td><td>${date(a.assigned_at)}</td><td>${status(a.status)}</td></tr>`).join(''):'<tr><td colspan="4"><div class="empty">No evaluator assignments.</div></td></tr>'}</tbody></table></div></section>`)}
async function evaluatorPage(){let as=await publicData('evaluator_assignments').catch(()=>[]);let ids=as.filter(a=>a.status==='active').map(a=>a.exam_id);let exams=ids.length?await result(sb.from('exams').select('id,title').in('id',ids)).catch(()=>[]):[];let attempts=ids.length?await result(sb.from('exam_attempts').select('*').in('exam_id',ids).in('status',['submitted','auto_submitted','evaluated'])).catch(()=>[]):[];let ans=attempts.length?await result(sb.from('student_answers').select('*').in('attempt_id',attempts.map(a=>a.id))).catch(()=>[]):[];let qs=ans.length?await result(sb.from('exam_questions').select('id,exam_id,question_text_snapshot,question_type,correct_answer_text_snapshot').in('id',ans.map(a=>a.exam_question_id))).catch(()=>[]):[];return shell(`<div class="page-title"><div><h1>Assigned scripts</h1><p>Review written answers for examinations assigned to you.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Examination</th><th>Question</th><th>Answer</th><th>Evaluation</th><th></th></tr></thead><tbody>${ans.length?ans.map(a=>{let q=qs.find(x=>x.id===a.exam_question_id),at=attempts.find(x=>x.id===a.attempt_id);return q?.question_type==='written'?`<tr><td>${esc(exams.find(e=>e.id===at?.exam_id)?.title||'Exam')}</td><td>${esc((q.question_text_snapshot||'').slice(0,80))}</td><td>${esc((a.written_answer_text||a.answer_image_path||'No response').slice(0,80))}</td><td>${status(a.evaluation_status||'pending')}</td><td><button class="btn btn-primary btn-sm" data-evaluate="${a.id}">Evaluate</button></td></tr>`:''}).join(''):'<tr><td colspan="5"><div class="empty">No assigned written scripts are available.</div></td></tr>'}</tbody></table></div></section>`)}
